/**
 * The PDF documents used by the Node tests and the browser checks, generated by pdf-builder.js.
 * Text is original to this repository (no third-party content). Each fixture targets one case
 * the enhanced PDF reader must handle; `pdfFixture(name)` returns the bytes.
 */
const { buildPdf, wrapWords, paragraph } = require("./pdf-builder");

const RAG_SENTENCE =
  "Retrieval-augmented generation improves factual accuracy by incorporating external knowledge.";

const HEADER = "Journal of Reproducible Fixtures, Vol. 3 (2026)";

function headerFooter(pageNumber) {
  return [
    { x: 72, y: 760, text: HEADER, size: 8 },
    { x: 300, y: 30, text: String(pageNumber), size: 8 },
  ];
}

/** 1. Single-column academic page: heading, abstract, body; the RAG sentence wraps across lines. */
function singleColumn() {
  const body = [
    "Large language models answer many questions fluently, but they still invent facts.",
    RAG_SENTENCE,
    "The retriever selects passages that the generator reads before it writes an answer.",
    "We measure how often the answer agrees with the retrieved evidence.",
  ].join(" ");
  const lines = wrapWords(body, 440, 11);
  return buildPdf({
    title: "Single column fixture",
    pages: [
      {
        texts: [
          ...headerFooter(1),
          { x: 72, y: 720, text: "1 Introduction", size: 14, font: "F2" },
          ...paragraph(lines, { x: 72, top: 690 }),
        ],
      },
    ],
  });
}

const LEFT_COLUMN = [
  "Dense retrieval maps queries and passages",
  "into one vector space. A query is answered",
  "by the passages whose vectors lie closest",
  "to its own vector, which makes the search",
  "fast even for very large collections.",
];
const RIGHT_COLUMN = [
  "Sparse methods count shared words instead.",
  "They remain strong baselines because the",
  "scores are easy to inspect and the index",
  "is cheap to update when documents change.",
  "Hybrid systems combine both signals.",
];

/** 2. Two-column page drawn in an interleaved order: left line 1, right line 1, left line 2 … */
function twoColumn() {
  const texts = [...headerFooter(1), { x: 72, y: 720, text: "2 Related Work", size: 14, font: "F2" }];
  for (let i = 0; i < LEFT_COLUMN.length; i++) {
    texts.push({ x: 72, y: 690 - i * 14, text: LEFT_COLUMN[i], size: 10 });
    texts.push({ x: 320, y: 690 - i * 14, text: RIGHT_COLUMN[i], size: 10 });
  }
  return buildPdf({ title: "Two column fixture", pages: [{ texts }] });
}

/** 3. Long wrapped paragraphs with a word hyphenated across a line break. */
function wrappedParagraphs() {
  const lines = [
    "Retrieval-augmented generation improves factual accuracy by incorpo-",
    "rating external knowledge into the prompt. The model then cites the",
    "passages it used, so a reader can check every claim against its source.",
    "",
    "A second paragraph discusses evaluation. Annotators compare each answer",
    "with the evidence and mark unsupported statements as hallucinations.",
  ];
  const texts = [...headerFooter(1)];
  let y = 700;
  for (const line of lines) {
    if (line) texts.push({ x: 72, y, text: line, size: 11 });
    y -= line ? 14 : 10;
  }
  return buildPdf({ title: "Wrapped paragraphs fixture", pages: [{ texts }] });
}

/** 4. Table cells and a formula line between body sentences. */
function tableFormula() {
  const texts = [
    ...headerFooter(1),
    { x: 72, y: 700, text: "Table 1 compares accuracy on the benchmark.", size: 11 },
    { x: 72, y: 670, text: "Model", size: 10, font: "F2" },
    { x: 250, y: 670, text: "Accuracy", size: 10, font: "F2" },
    { x: 400, y: 670, text: "Latency", size: 10, font: "F2" },
    { x: 72, y: 654, text: "Baseline", size: 10 },
    { x: 250, y: 654, text: "61.2", size: 10 },
    { x: 400, y: 654, text: "120 ms", size: 10 },
    { x: 72, y: 638, text: "Retrieval", size: 10 },
    { x: 250, y: 638, text: "74.8", size: 10 },
    { x: 400, y: 638, text: "180 ms", size: 10 },
    { x: 150, y: 600, text: "score(q, d) = cos(E(q), E(d)) + 0.5 * bm25(q, d)", size: 11, font: "F3" },
    { x: 72, y: 570, text: "The combined score is surprisingly robust across domains.", size: 11 },
  ];
  return buildPdf({ title: "Table and formula fixture", pages: [{ texts }] });
}

/** 5. A scanned-looking page: one image, no text. */
function imageOnly() {
  const w = 8;
  const h = 8;
  const rgb = Buffer.alloc(w * h * 3);
  for (let i = 0; i < w * h; i++) {
    const v = (i + Math.floor(i / w)) % 2 ? 230 : 40;
    rgb[i * 3] = v;
    rgb[i * 3 + 1] = v;
    rgb[i * 3 + 2] = v;
  }
  return buildPdf({
    title: "Image only fixture",
    pages: [{ image: { width: w, height: h, rgb, x: 72, y: 200, w: 468, h: 500 } }, { image: { width: w, height: h, rgb, x: 72, y: 200, w: 468, h: 500 } }],
  });
}

/** 6. Not a PDF at all after the header. */
function corrupt() {
  return Buffer.from("%PDF-1.7\n1 0 obj\n<< /Type /Catalog /Pages 9 0 R\nthis file was cut short", "latin1");
}

/** 7. Password protected (user password "manekilex"). */
function passwordProtected() {
  return buildPdf({
    title: "Password fixture",
    userPassword: "manekilex",
    ownerPassword: "owner-secret",
    pages: [{ texts: [{ x: 72, y: 700, text: "This protected page explains incorporating feedback carefully.", size: 12 }] }],
  });
}

/** 8. Several pages, a search term on pages 2 and 4. */
function multiPage() {
  const pages = [];
  for (let p = 1; p <= 6; p++) {
    const texts = [...headerFooter(p), { x: 72, y: 720, text: `Section ${p}`, size: 14, font: "F2" }];
    const body = [
      `Page ${p} describes one step of the evaluation pipeline in plain language.`,
      p === 2 || p === 4 ? "The calibration curve shows how confidence tracks accuracy." : "Nothing on this page mentions the special term.",
      "Each step reads the output of the previous one and writes a short report.",
    ];
    texts.push(...paragraph(body, { x: 72, top: 690 }));
    pages.push({ texts });
  }
  return buildPdf({ title: "Multi page fixture", pages });
}

/** 9. A long document for lazy rendering and memory checks. */
function longDocument(pageCount = 300) {
  const pages = [];
  for (let p = 1; p <= pageCount; p++) {
    const texts = [...headerFooter(p)];
    for (let l = 0; l < 30; l++) {
      texts.push({ x: 72, y: 720 - l * 22, text: `Page ${p} line ${l + 1}: the archive keeps every revision of the paper.`, size: 10 });
    }
    pages.push({ texts });
  }
  return buildPdf({ title: "Long fixture", pages });
}

const FIXTURES = {
  "single-column.pdf": singleColumn,
  "two-column.pdf": twoColumn,
  "wrapped.pdf": wrappedParagraphs,
  "table-formula.pdf": tableFormula,
  "image-only.pdf": imageOnly,
  "corrupt.pdf": corrupt,
  "password.pdf": passwordProtected,
  "multi-page.pdf": multiPage,
  "long.pdf": () => longDocument(),
};

const cache = new Map();
function pdfFixture(name) {
  if (!FIXTURES[name]) throw new Error(`unknown PDF fixture ${name}`);
  if (!cache.has(name)) cache.set(name, FIXTURES[name]());
  return cache.get(name);
}

module.exports = {
  pdfFixture,
  FIXTURE_NAMES: Object.keys(FIXTURES),
  RAG_SENTENCE,
  HEADER,
  LEFT_COLUMN,
  RIGHT_COLUMN,
  PASSWORD: "manekilex",
};
